// src/AIReimager.js
import React, { useState } from 'react'
import { supabase, supabaseAnonKey } from './supabaseClient'

function AIReimager({ site, onClose }) {
  const [prompt, setPrompt] = useState('')
  const [generating, setGenerating] = useState(false)
  const [generatedImage, setGeneratedImage] = useState(null)
  const [error, setError] = useState(null)

  const handleGenerate = async () => {
    setGenerating(true)
    setGeneratedImage(null)
    setError(null)

    try {
      // Call your deployed Edge Function.
      // We include the anon JWT so the function passes auth checks.
      const { data, error } = await supabase.functions.invoke('generate-image', {
        body: {
          prompt,
          imageUrl: site?.photo_url || undefined, // if your marker has a photo, we'll do img2img
          strength: 0.65,
        },
        headers: {
          // ✅ important: satisfy Edge Function auth requirement
          Authorization: `Bearer ${supabaseAnonKey}`,
        },
      })

      if (error) {
        // Supabase wraps non-2xx as an error object
        console.error('Edge error:', error)
        const details =
          typeof error?.context?.body === 'string'
            ? error.context.body
            : JSON.stringify(error?.context?.body || {}, null, 2)
        throw new Error(`Edge Function error\n${details}`)
      }

      if (!data?.imageUrl) {
        throw new Error('Edge Function returned no imageUrl')
      }

      setGeneratedImage(data.imageUrl)
    } catch (e) {
      console.error(e)
      setError(e.message || 'Failed to generate')
      alert('Error generating image: ' + (e.message || e))
    } finally {
      setGenerating(false)
    }
  }

  return (
    <div style={{
      position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.8)',
      display: 'flex', justifyContent: 'center', alignItems: 'center',
      zIndex: 3000, padding: 20
    }}>
      <div style={{
        backgroundColor: 'white', padding: 30, borderRadius: 12,
        width: '90%', maxWidth: 800, maxHeight: '90vh', overflow: 'auto',
        boxShadow: '0 4px 20px rgba(0,0,0,0.3)'
      }}>
        <h2 style={{ marginTop: 0 }}>✨ Reimagine: {site?.name}</h2>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20, marginBottom: 20 }}>
          <div>
            <h3>Original Derelict Site</h3>
            {site?.photo_url ? (
              <img
                src={site.photo_url}
                alt={site?.name || 'Site photo'}
                style={{ width: '100%', height: 250, objectFit: 'cover', borderRadius: 8, border: '2px solid #ddd' }}
              />
            ) : (
              <div style={{
                width: '100%', height: 250, backgroundColor: '#f0f0f0',
                display: 'flex', alignItems: 'center', justifyContent: 'center', borderRadius: 8
              }}>
                No photo available
              </div>
            )}
          </div>

          <div>
            <h3>AI Reimagined</h3>
            {generatedImage ? (
              <img
                src={generatedImage}
                alt="AI Generated"
                style={{ width: '100%', height: 250, objectFit: 'cover', borderRadius: 8, border: '2px solid #4CAF50' }}
              />
            ) : (
              <div style={{
                width: '100%', height: 250, backgroundColor: '#f0f0f0',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                borderRadius: 8, color: '#666'
              }}>
                {generating ? '🎨 Generating...' : 'Click generate to see magic'}
              </div>
            )}
          </div>
        </div>

        <div style={{ marginBottom: 20 }}>
          <label style={{ display: 'block', marginBottom: 10, fontWeight: 'bold' }}>
            How would you like to reimagine this site?
          </label>
          <textarea
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder="e.g., modern community market, green roof, glass atrium…"
            rows={3}
            style={{ width: '100%', padding: 12, border: '1px solid #ccc', borderRadius: 6, fontSize: 16, fontFamily: 'inherit' }}
          />
        </div>

        {error && <div style={{ marginBottom: 12, color: '#d32f2f', fontSize: 14 }}>{String(error)}</div>}

        <div style={{ display: 'flex', gap: 10 }}>
          <button
            onClick={handleGenerate}
            disabled={!prompt || generating}
            style={{
              flex: 1, padding: 12,
              backgroundColor: (!prompt || generating) ? '#ccc' : '#4CAF50',
              color: 'white', border: 'none', borderRadius: 6, fontSize: 16, fontWeight: 'bold',
              cursor: (!prompt || generating) ? 'not-allowed' : 'pointer'
            }}
          >
            {generating ? '✨ Generating…' : '🎨 Generate Reimagination'}
          </button>
          <button
            onClick={onClose}
            disabled={generating}
            style={{
              padding: '12px 24px', backgroundColor: '#666', color: 'white',
              border: 'none', borderRadius: 6, fontSize: 16, fontWeight: 'bold',
              cursor: generating ? 'not-allowed' : 'pointer'
            }}
          >
            Close
          </button>
        </div>

        {generatedImage && (
          <div style={{ marginTop: 20, textAlign: 'center' }}>
            <a
              href={generatedImage}
              download="reimagined-site.png"
              style={{
                display: 'inline-block', padding: '10px 20px',
                backgroundColor: '#2196F3', color: 'white', textDecoration: 'none',
                borderRadius: 6, fontWeight: 'bold'
              }}
            >
              💾 Download Reimagined Image
            </a>
          </div>
        )}
      </div>
    </div>
  )
}

export default AIReimager
